    static MapLocation localBfsPos = new MapLocation(-1, -1);
    public static void computeLocalBfsMasks() throws GameActionException {
        var loc = rc.getLocation();
        if(loc.equals(localBfsPos)) return;
        localBfsPos = loc;
        computeLocalDirt();
        computeLocalPassable();
    }

    public static void printLocalMask(long m1, long m2) {
        for(int i = 10; i >= 0; i--) {
            long row;
            if(i < 5) row = (m1 >> (i * 11)) & 0x7ff;
            else if(i == 5) row = (m1 >> 55) | ((m2 & 0x3f) << 6);
            else row = (m2 >> ((i - 6) * 11 + 5)) & 0x7ff;
            String s = "";
            for(int j = 0; j < 11; j++) {
                s += ((row & (1 << j)) != 0 ? "X " : ". ");
            }
            indicate(s);
        }
    }

    // symmetry checker
    public enum Symmetry {
        Unknown,
        Rotational,
        Horizontal,
        Vertical
    };
    public static int rsym = 1, hsym = 1, vsym = 1;
    public static boolean isSymmetryKnown() {
        return vsym + hsym + rsym == 1;
    }

    public static Symmetry getSymmetry() {
        return switch (vsym * 4 + hsym * 2 + rsym) {
            case 1 -> Symmetry.Rotational;
            case 2 -> Symmetry.Horizontal;
            case 4 -> Symmetry.Vertical;
            default -> Symmetry.Unknown;
        };
    }

    public static void setSymmetry(int cur_sym) {
        switch (cur_sym) {
            case 1 -> {
                CellTracker.hsym = CellTracker.vsym = 0;
                CellTracker.rsym = 1;
            }
            case 2 -> {
                CellTracker.rsym = CellTracker.vsym = 0;
                CellTracker.hsym = 1;
            }
            case 3 -> {
                CellTracker.rsym = CellTracker.hsym = 0;
                CellTracker.vsym = 1;
            }
        }
    }

