    public static void checkSymmetry() {
        switch(getSymmetry()) {
            case Horizontal -> {
                Profiler.begin();
                applyHor();
                Profiler.end("applyHorSymmetry");
            }
            case Unknown -> {
                Profiler.begin();
                // IF TLE: check one per turn instead of all 3
                if(hsym != 0) checkHor();
                if(vsym != 0) checkVer();
                if(rsym != 0) checkRot();
                Profiler.end("checkSymmetry");
            }
        }
    }
